insert into public.funding_opportunities (name, funder, level, url, what_it_funds, eligibility, deadline_text, amount_text, requires_legal_entity, fit, status, next_step, source_checked_on, notes) select 'Starthilfe Soziokultur (Pilotprojekte 1 bis 3 Jahre)', 'Stadt Zürich, Sozialdepartement', 'city', 'https://www.stadt-zuerich.ch/content/dam/web/de/stadtleben/wirtschaft-und-gewerbe/dokumente/kontraktmanagement/uebersicht-kredite-kriterien-soziokultur.pdf', 'Finanzierung von neuen, befristeten Projekten aufgrund eines ausgewiesenen Bedarfs oder einer innovativen Idee. Zu den genannten Wirkungen gehört, dass die Bevölkerung raschen Zugang zu Informationen über Aktivitäten im Quartier und andere Angebote erhält.', 'Nur juristische Personen (Verein, Stiftung usw.). Politisch und konfessionell neutral und unabhängig. Klarer Bezug zur Stadt Zürich. Das Sozialdepartement unterstützt nur subsidiär und erwartet Eigenleistungen und Beiträge anderer. Vereinsrechnung wird offengelegt. Kein Projekt kann von mehreren Departementen finanziert werden.', 'Siehe aktuelles Gesuchsformular (im Dokument nicht genannt)', null, true, 'good', 'idea', 'Aktuelle Version des Dokuments, Formular und Fristen beim Sozialdepartement (Soziokultur) erfragen. Das gefundene Dokument trägt die Angabe «Nov. 2017».', '2026-11-25', 'Passt am besten zur Idee der Plattform. Ein Verein ist Voraussetzung.' where not exists (select 1 from public.funding_opportunities where name = 'Starthilfe Soziokultur (Pilotprojekte 1 bis 3 Jahre)');
insert into public.funding_opportunities (name, funder, level, url, what_it_funds, eligibility, deadline_text, amount_text, requires_legal_entity, fit, status, next_step, source_checked_on, notes) select 'Quartierkultur: Kinderkultur und Quartierveranstaltungen', 'Stadt Zürich, Sozialdepartement', 'city', 'https://www.stadt-zuerich.ch/content/dam/web/de/stadtleben/wirtschaft-und-gewerbe/dokumente/kontraktmanagement/uebersicht-kredite-kriterien-soziokultur.pdf', 'Kinderkultur: künstlerische Angebote für Kinder (Theater, Musik, Malen, Film, Literatur, Tanz), Zielgruppe 2 bis 12 Jahre, vor allem benachteiligte Familien. Quartierveranstaltungen: in der Regel einmalige Anlässe, keine Serien und keine Betriebs- oder Lohnkosten.', 'Dieselben allgemeinen Kriterien wie oben (juristische Person, neutral, Bezug zur Stadt Zürich, subsidiär).', null, null, true, 'maybe', 'idea', 'Eher für Veranstaltungen mit Anbietern als für die Plattform selbst. Nur prüfen, wenn gemeinsam mit einem Anbieter ein Anlass geplant wird.', '2026-11-25', null where not exists (select 1 from public.funding_opportunities where name = 'Quartierkultur: Kinderkultur und Quartierveranstaltungen');
insert into public.funding_opportunities (name, funder, level, url, what_it_funds, eligibility, deadline_text, amount_text, requires_legal_entity, fit, status, next_step, source_checked_on, notes) select 'Gemeinnütziger Fonds (früher Lotteriefonds)', 'Kanton Zürich', 'canton', 'https://www.zh.ch/de/sport-kultur/swisslos-fonds/gemeinnuetziger-fonds.html', 'Gemeinnützige Projekte mit Bezug zum Kanton Zürich, deren Nutzen in erster Linie der Zürcher Bevölkerung zukommt.', 'Gemeinnützig, keine Erfüllung gesetzlicher öffentlicher Pflichten, Bezug zum Kanton Zürich. Kein Rechtsanspruch auf einen Beitrag. Je nach Bereich ist eine andere Stelle zuständig.', null, null, true, 'maybe', 'idea', 'Zuständige Stelle klären (Bildung, Soziales oder allgemein) und aktuelle Kriterien auf der offiziellen Seite lesen.', null, 'Angaben aus der Suchzusammenfassung der offiziellen Seite, noch nicht auf der Seite selbst bestätigt.' where not exists (select 1 from public.funding_opportunities where name = 'Gemeinnütziger Fonds (früher Lotteriefonds)');
insert into public.funding_opportunities (name, funder, level, url, what_it_funds, eligibility, deadline_text, amount_text, requires_legal_entity, fit, status, next_step, source_checked_on, notes) select 'Förderung von Integrationsprojekten (Kleinprojekte)', 'Kanton Zürich, Fachstelle Integration', 'canton', 'https://www.zh.ch/de/migration-integration/integration/foerderung-integrationsprojekte.html', 'Projekte zum Zusammenleben und zur Partizipation.', 'Gemeinden sowie öffentliche und private gemeinnützige Organisationen mit Sitz im Kanton Zürich.', null, null, true, 'unclear', 'idea', 'Nur sinnvoll, wenn ein Integrationsaspekt belegt ist (zum Beispiel mehrsprachiger Zugang für neu Zugezogene). Offizielle Seite lesen.', null, null where not exists (select 1 from public.funding_opportunities where name = 'Förderung von Integrationsprojekten (Kleinprojekte)');
insert into public.funding_opportunities (name, funder, level, url, what_it_funds, eligibility, deadline_text, amount_text, requires_legal_entity, fit, status, next_step, source_checked_on, notes) select 'Förderung der Gesundheit von Kindern bis 4 Jahren und ihren Eltern', 'Gesundheitsförderung Schweiz', 'federal', 'https://gesundheitsfoerderung.ch/', 'Laut eigener Publikation unterstützt die Stiftung Projekte zur Förderung der Gesundheit von Kindern bis vier Jahren und deren Eltern.', null, null, null, null, 'unclear', 'idea', 'Aktuelle Förderprogramme prüfen; häufig laufen sie über kantonale Programme.', null, null where not exists (select 1 from public.funding_opportunities where name = 'Förderung der Gesundheit von Kindern bis 4 Jahren und ihren Eltern');
insert into public.funding_opportunities (name, funder, level, url, what_it_funds, eligibility, deadline_text, amount_text, requires_legal_entity, fit, status, next_step, source_checked_on, notes) select 'Übersicht: Stiftungen für die Kinder- und Jugendförderung', 'Bundesamt für Sozialversicherungen (Verzeichnis)', 'federal', 'https://www.bsv.admin.ch/dam/bsv/de/dokumente/kinder/anleitungen/foerdermoeglichkeiten.pdf.download.pdf/2023_F%C3%BCr%20Kinder-%20und%20Jugendf%C3%B6rderung%20relevante%20Stiftungen_DE.pdf', 'Verzeichnis privater und staatlicher Stiftungen, die für die Kinder- und Jugendförderung relevant sind (Stand 2023).', null, null, null, null, 'unclear', 'idea', 'Verzeichnis durchgehen und passende Stiftungen einzeln auf ihrer Website prüfen.', null, 'Dient als Suchhilfe, nicht als Förderzusage.' where not exists (select 1 from public.funding_opportunities where name = 'Übersicht: Stiftungen für die Kinder- und Jugendförderung');
insert into public.funding_opportunities (name, funder, level, url, what_it_funds, eligibility, deadline_text, amount_text, requires_legal_entity, fit, status, next_step, source_checked_on, notes) select 'Private Stiftungen (zum Beispiel Jacobs Foundation, Mercator Stiftung Schweiz, Migros-Kulturprozent)', 'Verschiedene', 'foundation', null, null, null, null, null, null, 'unclear', 'idea', 'Noch nicht geprüft: Förderbereiche, Voraussetzungen und Fristen auf den Websites nachlesen.', null, 'Namen nur als Ideen genannt, keine Aussage zu Voraussetzungen.' where not exists (select 1 from public.funding_opportunities where name = 'Private Stiftungen (zum Beispiel Jacobs Foundation, Mercator Stiftung Schweiz, Migros-Kulturprozent)');
